+@Repository
+public class Neo4jGraphRepository implements AutoCloseable {
+    public static final Set<String> RELATION_TYPES = Set.of("HAS_CHAPTER", "COVERS", "IS_A", "HAS_TASK",
+            "HAS_EXAMPLE", "USED_FOR", "MEASURED_BY", "PREREQUISITE_FOR", "RELATED_TO");
+    private static final TransactionConfig QUERY_CONFIG = TransactionConfig.builder().withTimeout(Duration.ofSeconds(10)).build();
+    private final boolean enabled;
+    private final String database;
+    private final Driver driver;
+    private final boolean ownsDriver;
+
+    @Autowired
+    public Neo4jGraphRepository(Driver driver, @Value("${rag.graph.enabled:false}") boolean enabled,
+                                @Value("${spring.data.neo4j.database:neo4j}") String database) {
+        this.driver = driver;
